function policy(obs, params, mem) {
  var P = params;
  var th = obs[0], w = obs[1], vx = obs[2], vy = obs[3], h = obs[4];
  var qhA = obs[5], dqhA = obs[6], qkA = obs[7], dqkA = obs[8], footA = obs[9];
  var qhB = obs[10], dqhB = obs[11], qkB = obs[12], dqkB = obs[13], footB = obs[14];
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], a4 = obs[18], t = obs[19];

  if (!isFinite(th)) th = 0;
  if (!isFinite(w)) w = 0;
  if (!isFinite(vx)) vx = 0;
  if (!isFinite(vy)) vy = 0;
  if (!isFinite(h)) h = 1.2;
  if (!isFinite(t)) t = 0;
  if (!isFinite(qhA)) qhA = 0;
  if (!isFinite(dqhA)) dqhA = 0;
  if (!isFinite(qkA)) qkA = -0.5;
  if (!isFinite(dqkA)) dqkA = 0;
  if (!isFinite(qhB)) qhB = 0;
  if (!isFinite(dqhB)) dqhB = 0;
  if (!isFinite(qkB)) qkB = -0.5;
  if (!isFinite(dqkB)) dqkB = 0;
  if (!isFinite(a1)) a1 = 0;
  if (!isFinite(a2)) a2 = 0;
  if (!isFinite(a3)) a3 = 0;
  if (!isFinite(a4)) a4 = 0;
  footA = footA > 0.5 ? 1 : 0;
  footB = footB > 0.5 ? 1 : 0;

  var freq = P[0], hipAmp = P[1], hipBias = P[2];
  var kneeBias = P[3], kneeAmp = P[4], kneePhase = P[5], legOff = P[6];
  var kt = P[7], ktd = P[8], lean0 = P[9], kvS = P[10], vDes = P[11];
  var kh = P[12], khv = P[13], lift = P[14], gain = P[15], kHill = P[16];

  if (mem.ph === undefined) { mem.ph = 0; mem.need = 0; }

  var TAU = 6.283185307179586;

  var ramp = t * 2.2222222222;
  if (ramp > 1) ramp = 1;
  if (ramp < 0) ramp = 0;

  var hill = 0.55 * a2 + 0.22 * (a4 - a2);
  if (hill > 0.6) hill = 0.6;
  if (hill < -0.6) hill = -0.6;

  var need = a1 > a2 * 0.85 ? a1 : a2 * 0.85;
  if (need < 0) need = 0;
  if (need > mem.need) mem.need = need;
  else mem.need = mem.need * 0.93;
  if (mem.need > 0.5) mem.need = 0.5;

  var leanT = lean0 + kvS * (vx - vDes) - kHill * hill;
  if (leanT > 0.45) leanT = 0.45;
  if (leanT < -0.55) leanT = -0.55;
  var dTorso = kt * (leanT - th) - ktd * w;
  if (dTorso > 0.55) dTorso = 0.55;
  if (dTorso < -0.55) dTorso = -0.55;

  var hDes = 1.17;

  var pA = mem.ph - Math.floor(mem.ph);
  var pBraw = mem.ph + legOff;
  var pB = pBraw - Math.floor(pBraw);
  var hurry = 0;
  if (t > 0.6) {
    if (pA > 0.55 && footA) hurry += 2.4;
    if (pB > 0.55 && footB) hurry += 2.4;
  }
  var f = freq * (0.45 + 0.55 * ramp);
  if (f > 4.2) f = 4.2;
  if (f < 0.1) f = 0.1;
  var step = f + hurry;
  if (step > 5.0) step = 5.0;
  mem.ph += step * (1 / 60);
  mem.ph -= Math.floor(mem.ph);

  var phA = mem.ph;
  var qthA = hipBias + hipAmp * ramp * Math.cos(TAU * phA);
  var qtkA = kneeBias + kneeAmp * ramp * Math.sin(TAU * (phA + kneePhase));
  if (footA) qtkA += kh * (hDes - h) - khv * vy;
  if (phA > 0.5) qtkA -= lift * mem.need * Math.sin(TAU * (phA - 0.5));
  qthA += dTorso;
  if (qthA > 1.12) qthA = 1.12;
  if (qthA < -0.82) qthA = -0.82;
  if (qtkA > -0.1) qtkA = -0.1;
  if (qtkA < -1.62) qtkA = -1.62;

  var phB = mem.ph + legOff;
  phB -= Math.floor(phB);
  var qthB = hipBias + hipAmp * ramp * Math.cos(TAU * phB);
  var qtkB = kneeBias + kneeAmp * ramp * Math.sin(TAU * (phB + kneePhase));
  if (footB) qtkB += kh * (hDes - h) - khv * vy;
  if (phB > 0.5) qtkB -= lift * mem.need * Math.sin(TAU * (phB - 0.5));
  qthB += dTorso;
  if (qthB > 1.12) qthB = 1.12;
  if (qthB < -0.82) qthB = -0.82;
  if (qtkB > -0.1) qtkB = -0.1;
  if (qtkB < -1.62) qtkB = -1.62;

  var kpH = 285 * gain, kdH = 40 * gain, kpK = 215 * gain, kdK = 28 * gain;
  var u1 = (kpH * (qthA - qhA) - kdH * dqhA) / 257;
  var u2 = (kpK * (qtkA - qkA) - kdK * dqkA) / 172;
  var u3 = (kpH * (qthB - qhB) - kdH * dqhB) / 257;
  var u4 = (kpK * (qtkB - qkB) - kdK * dqkB) / 172;

  if (!isFinite(u1)) u1 = 0;
  if (!isFinite(u2)) u2 = 0;
  if (!isFinite(u3)) u3 = 0;
  if (!isFinite(u4)) u4 = 0;
  if (u1 > 1) u1 = 1; else if (u1 < -1) u1 = -1;
  if (u2 > 1) u2 = 1; else if (u2 < -1) u2 = -1;
  if (u3 > 1) u3 = 1; else if (u3 < -1) u3 = -1;
  if (u4 > 1) u4 = 1; else if (u4 < -1) u4 = -1;

  return [u1, u2, u3, u4];
}

function learn(lab) {
  var n = 17;
  var lo = [0.6, 0.12, -0.35, -1.15, 0.05, -0.30, 0.45, 0.0, 0.0, -0.50, 0.0, 0.6, 0.0, 0.0, 0.0, 0.5, 0.0];
  var hi = [2.4, 0.75, 0.35, -0.12, 0.80, 0.30, 0.62, 2.5, 1.0, 0.20, 0.8, 2.8, 3.0, 0.8, 2.5, 2.5, 1.2];
  var x0 = [1.5, 0.45, 0.0, -0.50, 0.40, 0.0, 0.52, 0.7, 0.2, -0.10, 0.15, 1.6, 0.8, 0.1, 0.8, 1.0, 0.3];

  var TRIAL_T = 10;
  try { if (lab && lab.seconds > 0) TRIAL_T = lab.seconds; } catch (e) { }
  var t0 = Date.now();
  var bestX = x0.slice(), bestS = -Infinity;
  var cache = {};

  function clampi(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function isNum(v) { return typeof v === "number" && isFinite(v); }

  function scoreOf(r) {
    if (!r || typeof r !== "object") return -1e9;
    var oc = r.outcome;
    if (oc === "invalid" || oc === "error") return -1e9;
    var d = isNum(r.distance) ? r.distance : 0;
    if (d < 0) d = 0;
    var tm = isNum(r.time) ? r.time : 0;
    if (tm < 0) tm = 0;
    if (tm > TRIAL_T) tm = TRIAL_T;
    var surv = (oc === "finished") ? 1.0 : (0.25 + 0.75 * (tm / TRIAL_T));
    return d * surv + 0.02 * tm;
  }

  function keyOf(x) {
    var s = "";
    for (var i = 0; i < n; i++) s += (Math.round(x[i] * 1e6)) + ";";
    return s;
  }

  function evaluate(x) {
    var kk = keyOf(x);
    if (cache[kk] !== undefined) return cache[kk];
    if (lab.trialsLeft() <= 0) return -Infinity;
    var r = null;
    try { r = lab.trial(x); } catch (e) { r = null; }
    var s = scoreOf(r);
    cache[kk] = s;
    if (s > bestS) { bestS = s; bestX = x.slice(); }
    return s;
  }

  function gauss() {
    var u = 0, v = 0;
    while (u <= 0) u = Math.random();
    while (v <= 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307179586 * v);
  }

  function toU(x) {
    var u = [];
    for (var i = 0; i < n; i++) u.push((x[i] - lo[i]) / (hi[i] - lo[i]));
    return u;
  }
  function toX(u) {
    var x = [];
    for (var i = 0; i < n; i++) x.push(lo[i] + clampi(u[i], 0, 1) * (hi[i] - lo[i]));
    return x;
  }
  function eye() {
    var A = [];
    for (var i = 0; i < n * n; i++) A.push(0);
    for (var i = 0; i < n; i++) A[i * n + i] = 1;
    return A;
  }
  function chol(A) {
    var L = [];
    for (var i = 0; i < n * n; i++) L.push(0);
    for (var i = 0; i < n; i++) {
      for (var j = 0; j <= i; j++) {
        var s = A[i * n + j];
        for (var k = 0; k < j; k++) s -= L[i * n + k] * L[j * n + k];
        if (i === j) {
          if (!(s > 1e-9)) return null;
          L[i * n + i] = Math.sqrt(s);
        } else {
          L[i * n + j] = s / L[j * n + j];
        }
      }
    }
    return L;
  }

  function outOfTime() { return (Date.now() - t0) > 165000; }

  evaluate(x0);

  var gf = [1.0, 1.4, 1.8, 2.2], ga = [0.3, 0.5], gk = [-0.45, -0.7], gg = [1.0, 1.8];
  var ia, ib, ic, id;
  for (ia = 0; ia < 4; ia++) {
    for (ib = 0; ib < 2; ib++) {
      for (ic = 0; ic < 2; ic++) {
        for (id = 0; id < 2; id++) {
          if (lab.trialsLeft() <= 0 || outOfTime()) break;
          var xg = x0.slice();
          xg[0] = gf[ia]; xg[1] = ga[ib]; xg[3] = gk[ic]; xg[15] = gg[id];
          evaluate(xg);
        }
      }
    }
  }

  var rr, i, j, k2;
  for (rr = 0; rr < 16; rr++) {
    if (lab.trialsLeft() <= 0 || outOfTime()) break;
    var ub = toU(bestX), ua = [];
    for (i = 0; i < n; i++) ua.push(clampi(ub[i] + gauss() * 0.22, 0, 1));
    evaluate(toX(ua));
  }
  for (rr = 0; rr < 8; rr++) {
    if (lab.trialsLeft() <= 0 || outOfTime()) break;
    var ub2 = [];
    for (i = 0; i < n; i++) ub2.push(Math.random());
    evaluate(toX(ub2));
  }

  var mean = toU(bestX);
  var sigma = 0.18;
  var C = eye();
  var lam = 13, mu = 5;
  var w = [], ws = 0;
  for (i = 0; i < mu; i++) { w.push(Math.log(mu + 0.5) - Math.log(i + 1)); ws += w[i]; }
  for (i = 0; i < mu; i++) w[i] /= ws;
  var cmu = 0.12;
  var stall = 0;

  while (lab.trialsLeft() > 0 && !outOfTime()) {
    var L = chol(C);
    if (!L) {
      C = eye();
      sigma *= 0.8;
      L = chol(C);
      if (!L) break;
    }
    var meanFit = evaluate(toX(mean));
    var offs = [];
    for (k2 = 1; k2 < lam; k2++) {
      if (lab.trialsLeft() <= 0) break;
      var z = [], y = [];
      for (i = 0; i < n; i++) z.push(gauss());
      for (i = 0; i < n; i++) {
        var acc = 0;
        for (j = 0; j <= i; j++) acc += L[i * n + j] * z[j];
        y.push(acc);
      }
      var u = [];
      for (i = 0; i < n; i++) u.push(clampi(mean[i] + sigma * y[i], 0, 1));
      var fit = evaluate(toX(u));
      var yy = [];
      for (i = 0; i < n; i++) yy.push((u[i] - mean[i]) / sigma);
      offs.push({ u: u, y: yy, fit: fit });
    }
    if (offs.length === 0) break;
    offs.sort(function (p, q) { return q.fit - p.fit; });

    var take = Math.min(mu, offs.length);
    var nm = [];
    for (i = 0; i < n; i++) nm.push(0);
    for (k2 = 0; k2 < take; k2++) {
      var wkv = w[k2];
      for (i = 0; i < n; i++) nm[i] += wkv * offs[k2].u[i];
    }
    mean = nm;

    var nC = [];
    for (i = 0; i < n * n; i++) nC.push((1 - cmu) * C[i]);
    for (k2 = 0; k2 < take; k2++) {
      var yk = offs[k2].y, wk = cmu * w[k2];
      for (i = 0; i < n; i++) {
        var yi = yk[i] * wk;
        if (yi === 0) continue;
        for (j = 0; j < n; j++) nC[i * n + j] += yi * yk[j];
      }
    }
    var tr = 0;
    for (i = 0; i < n; i++) tr += nC[i * n + i];
    if (tr > 1e-12) {
      var scl = n / tr;
      for (i = 0; i < n * n; i++) nC[i] *= scl;
      C = nC;
    }

    if (offs[0].fit > meanFit) { sigma *= 1.25; stall = 0; }
    else { sigma *= 0.86; stall++; }
    if (sigma < 0.01) sigma = 0.01;
    if (sigma > 0.45) sigma = 0.45;

    if (stall >= 8) {
      mean = toU(bestX);
      sigma = 0.22;
      C = eye();
      stall = 0;
    }
  }

  return bestX;
}

function policy(obs, params, mem) {
  var dt = 1 / 60;
  var L1 = 0.48, L2 = 0.37, HO = 0.355;
  var RMAX = 0.845, RMIN = 0.572;
  var MTO = 31.9856, MTH = 8.0256, MSH = 5.328;
  var MTOT = MTO + 2 * MTH + 2 * MSH;
  var W = MTOT * 9.98;

  function nx(v, d) { return (typeof v === "number" && isFinite(v)) ? v : d; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }

  var cfg = cl(Math.round(nx(params && params[0], 0)), 0, 7) | 0;
  var sH = (cfg & 1) ? -1 : 1;
  var mK = (cfg & 2) ? 1 : 0;
  var absH = (cfg & 4) ? 1 : 0;

  var th = nx(obs[0], 0), om = nx(obs[1], 0), vx = nx(obs[2], 0), vy = nx(obs[3], 0), hz = nx(obs[4], 1.15);
  var qhA = nx(obs[5], 0), dqhA = nx(obs[6], 0), qkA = nx(obs[7], -0.3), dqkA = nx(obs[8], 0);
  var fA = (obs[9] > 0.5) ? 1 : 0;
  var qhB = nx(obs[10], 0), dqhB = nx(obs[11], 0), qkB = nx(obs[12], -0.3), dqkB = nx(obs[13], 0);
  var fB = (obs[14] > 0.5) ? 1 : 0;
  var a1 = cl(nx(obs[15], 0), -3, 3), a2 = cl(nx(obs[16], 0), -3, 3);
  var a3 = cl(nx(obs[17], 0), -3, 3), a4 = cl(nx(obs[18], 0), -3, 3);
  var tt = nx(obs[19], 0);

  var freq = cl(nx(params[1], 1.5), 0.3, 4.5);
  var duty = cl(nx(params[2], 0.58), 0.35, 0.85);
  var stride = cl(nx(params[3], -0.18), -0.8, 0.8);
  var kCap = cl(nx(params[4], 0.33), -0.3, 1.5);
  var stepH = cl(nx(params[5], 0.12), -0.05, 0.4);
  var lean0 = cl(nx(params[6], -0.15), -0.9, 0.6);
  var kPl = cl(nx(params[7], 3), 0, 25);
  var kpH = cl(nx(params[8], 400), 10, 2000);
  var kpK = cl(nx(params[9], 300), 10, 2000);
  var kPz = cl(nx(params[10], 3000), -2000, 20000);
  var kDz = cl(nx(params[11], 1200), -1000, 8000);
  var F0 = cl(nx(params[12], 0), -500, 1000);
  var hDes = cl(nx(params[13], 1.13), 0.7, 1.4);
  var kV = cl(nx(params[14], 0.1), -1, 1.5);
  var kdH = 0.12 * kpH, kdK = 0.12 * kpK, kDl = 0.25 * kPl;

  function gh(x) {
    if (!(x > 0)) return 0;
    if (x <= 0.5) return a1 * (x * 2);
    if (x <= 1) return a1 + (a2 - a1) * ((x - 0.5) * 2);
    if (x <= 2) return a2 + (a3 - a2) * (x - 1);
    return a3 + (a4 - a3) * cl((x - 2) * 0.5, 0, 1);
  }

  var ct = Math.cos(th), stn = Math.sin(th);

  if (mem.ini === undefined) {
    mem.ini = 1;
    mem.p = [0, 0.5];
    mem.st = [1, 1];
    mem.air = [0, 0];
    mem.fx = [0, 0]; mem.fy = [0, 0];
    mem.gx = [0, 0]; mem.gy = [0, 0]; mem.gwy = [0, 0];
    mem.fz = [0, 0];
    mem.hp = hz;
    for (var i0 = 0; i0 < 2; i0++) {
      var qp0 = sH * (i0 === 0 ? qhA : qhB) - (absH ? th : 0);
      var qk0 = (i0 === 0 ? qkA : qkB);
      var kpp0 = mK ? -qk0 : qk0;
      var bx0 = L1 * Math.sin(qp0) + L2 * Math.sin(qp0 + kpp0);
      var by0 = -HO - L1 * Math.cos(qp0) - L2 * Math.cos(qp0 + kpp0);
      var wx0 = bx0 * ct - by0 * stn, wy0 = bx0 * stn + by0 * ct;
      mem.fx[i0] = wx0; mem.fy[i0] = wy0;
      mem.gx[i0] = wx0; mem.gy[i0] = wy0; mem.gwy[i0] = wy0 + hz;
      if (!(i0 === 0 ? fA : fB)) {
        mem.st[i0] = 0;
        mem.p[i0] = cl(duty + 0.15, 0, 0.98);
        mem.air[i0] = 1;
      }
    }
  }

  var comX = 0, comY = 0;
  for (var j = 0; j < 2; j++) {
    var qhp2 = sH * (j === 0 ? qhA : qhB) - (absH ? th : 0);
    var qkk2 = (j === 0 ? qkA : qkB);
    var qkp2 = mK ? -qkk2 : qkk2;
    var aT = qhp2, aS = qhp2 + qkp2;
    var knx = L1 * Math.sin(aT), kny = -HO - L1 * Math.cos(aT);
    var tcx = 0.24 * Math.sin(aT), tcy = -HO - 0.24 * Math.cos(aT);
    var scx = knx + 0.185 * Math.sin(aS), scy = kny - 0.185 * Math.cos(aS);
    comX += MTH * (tcx * ct - tcy * stn) + MSH * (scx * ct - scy * stn);
    comY += MTH * (tcx * stn + tcy * ct) + MSH * (scx * stn + scy * ct);
  }
  comX /= MTOT; comY /= MTOT;

  var leanT = cl(lean0 + kV * (vx - 1.4), -0.5, 0.5);
  var dT = cl(kPl * (th - leanT) + kDl * om, -0.8, 0.8);

  var nSt = cl(fA + fB, 1, 2);

  var out = [0, 0, 0, 0];
  for (var i = 0; i < 2; i++) {
    var qhS = (i === 0 ? qhA : qhB), dqhS = (i === 0 ? dqhA : dqhB);
    var qkS = (i === 0 ? qkA : qkB), dqkS = (i === 0 ? dqkA : dqkB);
    var cts = (i === 0 ? fA : fB);
    var p = mem.p[i], s = mem.st[i];

    var qhp = sH * qhS - (absH ? th : 0);
    var qkp = mK ? -qkS : qkS;
    var bxa = L1 * Math.sin(qhp) + L2 * Math.sin(qhp + qkp);
    var bya = -HO - L1 * Math.cos(qhp) - L2 * Math.cos(qhp + qkp);
    var dax = bxa * ct - bya * stn, day = bxa * stn + bya * ct;

    if (tt > 0.08) p += freq * dt;
    var wr = 0;
    if (p >= 1) { p -= 1; wr = 1; }

    if (s === 1) {
      if (p >= duty) { s = 0; p = duty; mem.air[i] = 0; }
    } else {
      if (!cts) mem.air[i] = 1;
      if (mem.air[i] && cts && p > duty + 0.05) {
        s = 1; p = 0;
        mem.gx[i] = dax; mem.gy[i] = day; mem.gwy[i] = day + hz;
        mem.fx[i] = dax; mem.fy[i] = day;
        mem.fz[i] = 0;
      } else if (wr) {
        s = 1; p = 0;
        mem.fx[i] = dax; mem.fy[i] = day;
      }
    }
    mem.p[i] = p; mem.st[i] = s;

    if (s === 1) {
      mem.fx[i] -= vx * dt;
      mem.fy[i] -= (hz - mem.hp);
      if (!cts) mem.fz[i] += 2500 * dt; else mem.fz[i] -= 5000 * dt;
      mem.fz[i] = cl(mem.fz[i], 0, 1500);
    } else {
      var u = cl((p - duty) / (1 - duty), 0, 1);
      var fxt = cl(comX + kCap * vx + stride, -0.6, 1.2);
      mem.fx[i] += (fxt - mem.fx[i]) * cl(dt / 0.09, 0, 1);
      var arc = (u < 0.12) ? (u / 0.12) : ((u > 0.88) ? ((1 - u) / 0.12) : 1);
      var fyT = mem.gwy[i] + gh(mem.fx[i]) + stepH * arc - hz;
      if (u > 0.75) fyT -= 0.10 * (u - 0.75) * 4;
      mem.fy[i] += (fyT - mem.fy[i]) * cl(dt / 0.07, 0, 1);
      mem.fz[i] = 0;
    }

    var bx = mem.fx[i] * ct + mem.fy[i] * stn;
    var by = -mem.fx[i] * stn + mem.fy[i] * ct;
    var rx = bx, ry = by + HO;
    if (ry > -0.06) ry = -0.06;
    var rr = Math.sqrt(rx * rx + ry * ry);
    if (!(rr > 0.001)) { rr = 0.001; rx = 0; ry = -0.001; }
    var beta = Math.atan2(rx, -ry);
    var rG = cl(rr, RMIN, RMAX);
    var ca = cl((L1 * L1 + rG * rG - L2 * L2) / (2 * L1 * rG), -1, 1);
