    if (j >= 0 && j < 4 && t < dur) out[j] = cmd;

    const angIdx = [5, 7, 10, 12];
    const spdIdx = [6, 8, 11, 13];
    if (!mem.pi) mem.pi = { sum: 0, n: 0, start: undefined, end: undefined };
    const pi = mem.pi;

    if (j >= 0 && j < 4) {
