  const spin = fin(O[1], 0);
  const vx = fin(O[2], 0);
  const vy = fin(O[3], 0);
  const height = fin(O[4], 1.0);

  const qHs = [fin(O[5], 0), fin(O[10], 0)];
  const qKs = [fin(O[7], -0.1), fin(O[12], -0.1)];
  const qdHs = [fin(O[6], 0), fin(O[11], 0)];
