    mem.init = 1;
    mem.lastT = t;
    mem.phase = g(0, 0.0);
    mem.initHeight = height;
    mem.initPhi = [curPhi[0], curPhi[1]];
    const hipY0 = height - TH * Math.cos(theta);
    mem.initFootY = [hipY0 + fky[0], hipY0 + fky[1]];
    mem.emergency = 0;
    mem.emergencyT = 0;
    mem.inf = {
      maxAbsAngle: 0,
      maxAbsSpin: 0,
      maxHeight: 0,
      minHeight: 99,
      maxJointSpeed: 0,
      sumVx: 0,
      contactA: 0,
      contactB: 0,
      dangerTime: 0,
      lateN: 0,
      lateSumVx: 0,
      lateSumVx2: 0,
      lateMaxAbsAngle: 0,
      lateMinHeight: 99,
      lateMaxAbsSpin: 0,
      lateContactA: 0,
      lateContactB: 0,
      lateDanger: 0,
      lateBothAir: 0
