  const freqBase = g(1, 1.45);
  const freqV = g(2, 0.05);
  const stepA = cl(g(3, 0.14), 0.02, 0.30);
  const duty = cl(g(4, 0.72), 0.45, 0.92);
  const Hbase = cl(g(5, 1.08), 0.82, 1.18);
  const clearance = cl(g(6, 0.10), 0.01, 0.40);
  const vTarget = g(8, 0.45);
  const legOffset = cl(g(19, 0.50), 0.25, 0.75);
  const stancePush = g(20, 0.0);
  const obsGain = g(21, 0.5);
  const braceStart = cl(g(22, 8.0), 4.5, 8.4);
  const braceFade = Math.max(0.15, g(23, 0.90));
  const braceSpread = cl(g(24, 0.16), 0.0, 0.35);
  const braceH = cl(g(25, 1.02), 0.80, 1.15);
  const emergencyTh = cl(g(26, 0.95), 0.40, 2.5);
  const startupDur = Math.max(0.1, g(27, 0.70));
  const obsMargin = g(36, 0.03);

