    const stance = s < duty;

    let phiWalk = 0;
    let footYWalk = 0;

    if (stance) {
      const u = cl(s / Math.max(0.001, duty), 0, 1);
      phiWalk = stepA * (1 - 2 * u) + stancePush * Math.sin(Math.PI * u);
      phiWalk = cl(phiWalk, -0.55, 0.55);
      footYWalk = terrainH(phiWalk);
    } else {
      const u = cl((s - duty) / Math.max(0.001, 1 - duty), 0, 1);
      const sm = smooth(u);
      phiWalk = -stepA + 2 * stepA * sm;

      const Tstance = duty / Math.max(0.40, freq);
      const fb =
        g(30, 0.20) * vx * Tstance +
        g(31, 0.0) * (theta - lean) +
        g(32, 0.0) * spin +
        g(33, 0.0) * (vx - vTarget);
      phiWalk += fb * sm;
      phiWalk = cl(phiWalk, -0.55, 0.55);

      const gT = terrainH(phiWalk);
      let maxH = gT;
      const cp = curPhi[i];
      for (let k = 0; k <= 6; k++) {
        const d = cp + (phiWalk - cp) * (k / 6);
        const h = terrainH(d);
