      const obsLift = Math.max(0, maxH - gT + obsMargin) * Math.sin(Math.PI * u);
      footYWalk = gT + Math.max(arc, obsLift);
    }

    const bracePhi = (i === 0) ? braceSpread : -braceSpread;
    const braceY = terrainH(bracePhi);

    let phi = phiWalk * (1 - braceW) + bracePhi * braceW;
    let footY = footYWalk * (1 - braceW) + braceY * braceW;

    phi = mem.initPhi[i] * (1 - st) + phi * st;
    footY = mem.initFootY[i] * (1 - st) + footY * st;

    let xRel = phi - TH * Math.sin(theta);
    let yRel = footY - hipYdes;

    xRel = cl(xRel, -0.88, 0.88);
    if (!(yRel < -0.015)) yRel = -0.015;

    let rr = Math.sqrt(xRel * xRel + yRel * yRel);
    rr = cl(rr, 0.12, L1 + L2 - 0.005);

    const cosK = cl((rr * rr - L1 * L1 - L2 * L2) / (2 * L1 * L2), -1, 1);
    let qKt = -Math.acos(cosK);

    const gamma = Math.atan2(xRel, -yRel);
    const delta = gamma - Math.atan2(
      L2 * Math.sin(qKt),
      L1 + L2 * Math.cos(qKt)
    );
    let qHt = delta - theta;

    qHt +=
      g(9, 0.60) * (theta - lean) +
      g(10, 0.10) * spin +
      g(11, 0.10) * (vx - vTarget);

    qKt +=
      g(12, 2.0) * (hEff - height) -
      g(13, 0.25) * vy;

    qHt = cl(qHt, -0.88, 1.18);
    qKt = cl(qKt, -1.68, -0.06);

    let tauH = kp * (qHt - qHs[i]) - kd * qdHs[i];
    let tauK = kpK * (qKt - qKs[i]) - kdK * qdKs[i];

    tauH +=
      g(16, 0.15) * (theta - lean) +
      g(17, 0.02) * spin +
      g(18, -0.05) * (vx - vTarget);

    tauH += braceW * (
      g(34, 0.30) * (theta - lean) +
      g(35, 0.05) * spin
    );

    const sH = (sg[2 * i] === -1) ? -1 : 1;
    const sK = (sg[2 * i + 1] === -1) ? -1 : 1;

    out[2 * i] = sH * cl(tauH, -1, 1);
    out[2 * i + 1] = sK * cl(tauK, -1, 1);
  }

  for (let j = 0; j < 4; j++) {
    if (!isFinite(out[j])) out[j] = 0;
    out[j] = cl(out[j], -1, 1);
  }

  const inf = mem.inf;
  const aa = Math.abs(theta);
  const asp = Math.abs(spin);
  const mjs = Math.max(
    Math.abs(qdHs[0]), Math.abs(qdHs[1]),
    Math.abs(qdKs[0]), Math.abs(qdKs[1])
  );
  const dangerRate =
    Math.max(0, Math.abs(theta - lean) - 0.60) +
    Math.max(0, 0.50 - height) * 2 +
    Math.max(0, asp - 2.50) * 0.20;

  if (aa > inf.maxAbsAngle) inf.maxAbsAngle = aa;
  if (asp > inf.maxAbsSpin) inf.maxAbsSpin = asp;
  if (height > inf.maxHeight) inf.maxHeight = height;
  if (height < inf.minHeight) inf.minHeight = height;
  if (mjs > inf.maxJointSpeed) inf.maxJointSpeed = mjs;

  inf.sumVx += vx * dt;
  inf.contactA += contact[0] * dt;
  inf.contactB += contact[1] * dt;
  inf.dangerTime += dangerRate * dt;

  if (t > 6.5) {
    inf.lateN++;
    inf.lateSumVx += vx;
    inf.lateSumVx2 += vx * vx;
    inf.lateContactA += contact[0];
    inf.lateContactB += contact[1];
    inf.lateDanger += dangerRate;
    if (contact[0] === 0 && contact[1] === 0) inf.lateBothAir++;
    if (aa > inf.lateMaxAbsAngle) inf.lateMaxAbsAngle = aa;
    if (height < inf.lateMinHeight) inf.lateMinHeight = height;
    if (asp > inf.lateMaxAbsSpin) inf.lateMaxAbsSpin = asp;
  }

  inf.lateAvgVx = inf.lateN > 0 ? inf.lateSumVx / inf.lateN : 0;
  inf.lateVxVar = inf.lateN > 0
    ? Math.max(0, inf.lateSumVx2 / inf.lateN - inf.lateAvgVx * inf.lateAvgVx)
    : 0;
  inf.t = t;
  inf.theta = theta;
  inf.spin = spin;
  inf.vx = vx;
  inf.vy = vy;
  inf.height = height;
  inf.footA = contact[0];
  inf.footB = contact[1];
  inf.braceW = braceW;

