    -0.08, 0.0, 6.0, 0.2, 0.02, 0.85, 0.5, 0.2, 0.5, 0.5,
    -0.5, -1.0, -0.5, -1.0, -0.5, -0.5, 0.0
  ];
  const HI = [
    6.283, 2.5, 0.30, 0.22, 0.88, 1.15, 0.30, 0.12, 1.2, 1.5,
    0.5, 0.5, 6.0, 1.0, 16.0, 1.8, 1.0, 0.5, 1.0, 0.62,
    0.08, 1.0, 8.2, 1.5, 0.28, 1.10, 2.0, 1.5, 1.6, 1.6,
    0.8, 1.0, 0.5, 1.0, 1.5, 0.8, 0.10
  ];
