    0.0, 1.45, 0.05, 0.14, 0.72, 1.08, 0.10, -0.02, 0.45, 0.60,
    0.10, 0.10, 2.0, 0.25, 8.0, 0.60, 0.15, 0.02, -0.05, 0.50,
    0.0, 0.5, 8.0, 0.9, 0.16, 1.02, 0.95, 0.7, 1.0, 1.0,
