    if (r.outcome !== 'finished') d -= 4;
    return d;
  };

  let best = null;
  const archive = [];
  const evalX = (x) => {
    if (lab.trialsLeft() <= 0 || timeUp()) return null;
    let r;
    try {
      r = lab.trial(toParams(x));
    } catch (e) {
      return null;
    }
    const s = scoreOf(r);
    const c = { x: x.slice(), s, params: toParams(x) };
    archive.push(c);
    if (!best || c.s > best.s) best = c;
    return c;
  };

  // Phase 1: seed, tight probes around the seed, and a few global samples.
  const xs = toX(seed);
  evalX(xs);
  const sigs = [0.02, 0.05, 0.1];
  let k = 0;
  while (lab.trialsLeft() > 0 && !timeUp() && k < 40) {
    let x;
    if (k % 5 === 4) {
      x = P.map(() => Math.random());
    } else {
      const sg = sigs[k % sigs.length];
      x = xs.map((v) => c01(v + sg * gauss()));
    }
    k++;
    if (!evalX(x)) break;
  }

  if (!best) return toParams(xs);

  // Phase 2: mean-shift evolution strategy with 1/5-style step control and elite restarts.
  const lam = 12, mu = 4;
  const w = [];
  let wsum = 0;
  for (let i = 0; i < mu; i++) {
    w[i] = Math.log(mu + 0.5) - Math.log(i + 1);
    wsum += w[i];
  }
  for (let i = 0; i < mu; i++) w[i] /= wsum;

  let m = best.x.slice();
  let sig = 0.05;
  let gen = 0;
  let lastImprove = 0;

  while (lab.trialsLeft() > 0 && !timeUp()) {
    gen++;
    const prevBest = best.s;
    const pop = [];
    let stop = false;
    for (let j = 0; j < lam; j++) {
      if (lab.trialsLeft() <= 0 || timeUp()) { stop = true; break; }
      const x = m.map((v) => c01(v + sig * gauss()));
      const c = evalX(x);
      if (!c) { stop = true; break; }
      pop.push(c);
    }
    if (pop.length === 0) break;
    pop.sort((a, b) => b.s - a.s);

    const cnt = pop.filter((c) => c.s > prevBest).length;
    const used = Math.min(mu, pop.length);
    let ws = 0;
    for (let i = 0; i < used; i++) ws += w[i];
    const nm = new Array(n).fill(0);
    for (let i = 0; i < used; i++) {
      for (let d = 0; d < n; d++) nm[d] += (w[i] / ws) * pop[i].x[d];
    }
    m = nm;

    sig *= Math.exp(0.6 * (cnt / lam - 0.2));
    sig = Math.max(0.004, Math.min(0.3, sig));

    if (best.s > prevBest) lastImprove = gen;
    if (stop) break;

    if (gen - lastImprove > 10 || sig < 0.006) {
      const r = Math.random();
      if (r < 0.4) {
        m = best.x.slice();
        sig = 0.06;
      } else if (r < 0.8) {
        const sorted = archive.slice().sort((a, b) => b.s - a.s);
        const kk = Math.min(sorted.length, 6);
        const pick = sorted[Math.floor(Math.random() * kk)];
        m = pick.x.slice();
        sig = 0.1;
      } else {
        m = P.map(() => Math.random());
        sig = 0.25;
      }
      lastImprove = gen;
    }
  }

  return best ? best.params : toParams(xs);
}
